package dev.mineagent.runtime.neoforge.ui;
import com.fasterxml.jackson.databind.*;import dev.mineagent.runtime.core.config.*;import dev.mineagent.runtime.neoforge.MineAgentRuntimeServices;import dev.mineagent.runtime.api.model.*;import net.minecraft.server.level.ServerPlayer;import java.util.*;import java.util.concurrent.*;import java.util.function.*;

public final class ServerModelCapabilities {
 private static final ObjectMapper JSON=new ObjectMapper();private static final ExecutorService IO=Executors.newVirtualThreadPerTaskExecutor();
 private record Selection(String base,String model,ModelCapabilityProfiles.Profile profile){}
 private static Selection selected(ServerPlayer p,UUID agent,String model,String capability){var config=MineAgentRuntimeServices.config(p.level().getServer());var values=config.snapshot().values();String base=values.getOrDefault("provider.openai.baseUrl","");if(!WebSettingsCatalog.safeUrl(base)||base.isBlank())throw new IllegalArgumentException("MODEL_API_NOT_CONFIGURED");if(model.isBlank()){var choice=AgentModelSettings.read(values,MineAgentRuntimeServices.worldId(p.level().getServer()),agent);String role=capability.equals("vision")?values.getOrDefault("provider.openai.role.vision",""):"";model=!role.isBlank()?role:choice.mode().equals("CUSTOM")?choice.model():values.getOrDefault("provider.openai.model","");}if(!AgentModelSettings.validModel(model))throw new IllegalArgumentException("MODEL_ID_NOT_CONFIGURED");return new Selection(base,model,ModelCapabilityProfiles.read(values,base,model));}
 public static Map<String,Object> read(ServerPlayer p,UUID agent,String model){var selection=selected(p,agent,model,"");var out=new LinkedHashMap<String,Object>(ModelCapabilityProfiles.wire(selection.profile()));out.put("baseUrl",selection.base());out.put("screenshots",MineAgentRuntimeServices.config(p.level().getServer()).flag("resource.capture."+p.getUUID(),false));out.put("status","OBSERVED");return out;}
 public static Map<String,Object> save(ServerPlayer p,Map<String,String> args)throws Exception{UUID agent=UUID.fromString(args.get("agentId"));ServerAgentModels.authorize(p,Map.of("agentId",agent.toString()));var selection=selected(p,agent,args.getOrDefault("model",""),"");var config=MineAgentRuntimeServices.config(p.level().getServer());ModelCapabilityProfiles.save(config,selection.base(),selection.model(),Long.parseLong(args.get("expectedRevision")),ModelCapabilityProfiles.Support.valueOf(args.get("vision")),ModelCapabilityProfiles.Support.valueOf(args.get("tools")),Integer.parseInt(args.get("contextTokens")),"MANUAL");if(args.containsKey("screenshots")){if(!Set.of("true","false").contains(args.get("screenshots")))throw new IllegalArgumentException("MODEL_CAPTURE_BOOLEAN");var result=config.apply(new dev.mineagent.runtime.api.config.ConfigPatch(config.revision(),Map.of("resource.capture."+p.getUUID(),args.get("screenshots"))),true);if(!result.accepted())throw new IllegalStateException(result.errorCode());}return read(p,agent,selection.model());}
 public static CompletableFuture<Map<String,Object>> inspect(ServerPlayer p,UUID agent,JsonNode args,BooleanSupplier permit){
  var selection=selected(p,agent,args.path("model").asText(""),args.path("capability").asText(""));if(!args.path("probe").asBoolean())return CompletableFuture.completedFuture(read(p,agent,selection.model()));ServerAgentModels.authorize(p,Map.of("agentId",agent.toString()));String capability=args.path("capability").asText("vision");if(!Set.of("vision","tools").contains(capability))throw new IllegalArgumentException("MODEL_PROBE_CAPABILITY");var server=p.level().getServer();var config=MineAgentRuntimeServices.config(server);String key=config.secretValue("provider.openai.apiKey").orElse("");
  return CompletableFuture.supplyAsync(()->{try{if(!permit.getAsBoolean())throw new IllegalStateException("MODEL_PROBE_CANCELLED");var provider=new dev.mineagent.runtime.worker.provider.OpenAiCompatibleProvider(java.net.URI.create(selection.base()),key,selection.model(),java.time.Duration.ofSeconds(45));boolean passed;
   if(capability.equals("vision")){var colors=List.of(new Object[]{"red",java.awt.Color.RED},new Object[]{"blue",java.awt.Color.BLUE},new Object[]{"green",java.awt.Color.GREEN},new Object[]{"yellow",java.awt.Color.YELLOW});var order=new ArrayList<>(colors);Collections.shuffle(order,new java.security.SecureRandom());var images=new ArrayList<ModelImage>();for(int i=0;i<2;i++){var img=new java.awt.image.BufferedImage(96,96,java.awt.image.BufferedImage.TYPE_INT_RGB);var graphics=img.createGraphics();graphics.setColor((java.awt.Color)order.get(i)[1]);graphics.fillRect(0,0,96,96);graphics.dispose();images.add(dev.mineagent.runtime.worker.resources.ResourceImages.encode(img,9216));img.flush();}var answer=provider.complete(new ModelRequest(ModelCapability.VISION,"Name the dominant color of each attached image, in attachment order. Reply with only two English color names separated by a comma.",images)).text().toLowerCase(Locale.ROOT);int first=answer.indexOf(order.get(0)[0].toString()),second=answer.indexOf(order.get(1)[0].toString());passed=first>=0&&second>first;}
   else{String value=UUID.randomUUID().toString();String schema="{\"type\":\"object\",\"properties\":{\"value\":{\"type\":\"string\"}},\"required\":[\"value\"],\"additionalProperties\":false}";var completion=provider.completeWithTools(new ModelRequest(ModelCapability.SEMANTIC,"Call report_probe once with value exactly "+value+". This is a harmless capability test."),List.of(new dev.mineagent.runtime.worker.provider.ToolDefinition("report_probe","Return the test value",schema)));passed=completion.toolCalls().size()==1&&completion.toolCalls().getFirst().name().equals("report_probe")&&JSON.readTree(completion.toolCalls().getFirst().argumentsJson()).path("value").asText().equals(value);}
   return passed;
  }catch(Exception e){throw new CompletionException(e);}},IO).handle((passed,error)->server.submit(()->{try{if(!permit.getAsBoolean()||server.getPlayerList().getPlayer(p.getUUID())!=p||!Objects.equals(config.snapshot().values().get("provider.openai.baseUrl"),selection.base()))throw new IllegalStateException("MODEL_PROBE_CONTEXT_CHANGED");if(error!=null||!Boolean.TRUE.equals(passed)){var result=new LinkedHashMap<String,Object>(read(p,agent,selection.model()));result.put("probe","INCONCLUSIVE");result.put("diagnostic",error==null?"Provider did not return the requested image/tool evidence":dev.mineagent.runtime.core.conversation.ToolFailure.safe(error.getMessage()));return result;}var old=selection.profile();ModelCapabilityProfiles.save(config,selection.base(),selection.model(),old.revision(),capability.equals("vision")?ModelCapabilityProfiles.Support.YES:old.vision(),capability.equals("tools")?ModelCapabilityProfiles.Support.YES:old.tools(),old.contextTokens(),"PROBE");var result=new LinkedHashMap<String,Object>(read(p,agent,selection.model()));result.put("probe","PASSED");return result;}catch(Exception e){throw new CompletionException(e);}})).thenCompose(f->f);
 }
 private ServerModelCapabilities(){}
}
